/**
 * `RegistryTraitSurface` / `getBehaviorsByRole` / `getTraitSurface` — the
 * W0 per-trait exposure axes `RegistryEntry` gained (`docs/Almadar_Rabit.md`
 * ancestry: `Almadar_Rabit_V3.md`/`Almadar_Rabit_V4.md`). Runs against the
 * on-disk `behaviors-registry.json` (regenerated by `almadar-sync behaviors`)
 * — same fixture style as `registry-output.test.ts`.
 */
import { describe, it, expect } from 'vitest';
import type { FactoryTraitSignature } from '@almadar/core';
import {
  getBehaviorsByRole,
  getTraitSurface,
  getBehaviorRegistry,
  type RegistryTraitSurface,
} from '../behaviors/query';

describe('getBehaviorsByRole', () => {
  it('finds std-platformer-body under role "authority" (ticks + entityContract.provides, no render)', async () => {
    const entries = await getBehaviorsByRole('authority');
    const names = entries.map((e) => e.name);
    expect(names).toContain('std-platformer-body');
  });

  it('every returned entry actually carries the role in its roles union', async () => {
    const entries = await getBehaviorsByRole('renderer');
    expect(entries.length).toBeGreaterThan(0);
    for (const e of entries) {
      expect(e.roles ?? []).toContain('renderer');
    }
  });

  it('an unstamped role (no entries) returns an empty array, never throws', async () => {
    // 'frame' is a narrow promotion (an organism with ≥2 unclassified ref
    // traits sharing one linkedEntity) — legitimately rare/absent in the
    // real registry today; the call must still resolve cleanly either way.
    await expect(getBehaviorsByRole('frame')).resolves.toBeInstanceOf(Array);
  });
});

describe('getTraitSurface', () => {
  it('returns the named trait surface for a known behavior + trait', async () => {
    const registry = await getBehaviorRegistry();
    const entry = registry['std-platformer-body'];
    expect(entry?.traits?.[0]).toBeDefined();
    const traitName = entry.traits![0].name;
    const surface = await getTraitSurface('std-platformer-body', traitName);
    expect(surface).not.toBeNull();
    expect(surface?.role).toBe('authority');
  });

  it('returns null for an unknown behavior', async () => {
    expect(await getTraitSurface('std-does-not-exist', 'Whatever')).toBeNull();
  });

  it('returns null for an unknown trait on a known behavior', async () => {
    expect(await getTraitSurface('std-platformer-body', 'NotARealTrait')).toBeNull();
  });
});

// ============================================================================
// Compile-time drift guard: every FactoryTraitSignature field this registry
// surface mirrors must exist (name + type) on RegistryTraitSurface, so the
// two records cannot silently diverge again.
// ============================================================================

type _AssertSurfaceCoversSignature = FactoryTraitSignature extends {
  name: infer Name;
  ref?: infer Ref;
  emittedEvents: infer Emitted;
  listenedEvents: infer Listened;
  transitionEvents?: infer Transitions;
  events?: infer Events;
  overridableConfigKeys: infer Config;
  capabilities: infer Capabilities;
  linkedEntity?: infer LinkedEntity;
  entityRebindable?: infer Rebindable;
  entityContract?: infer Contract;
  definerKnobs?: infer Definer;
}
  ? RegistryTraitSurface extends {
      name: Name;
      ref?: Ref;
      emittedEvents: Emitted;
      listenedEvents: Listened;
      transitionEvents?: Transitions;
      events?: Events;
      overridableConfigKeys: Config;
      capabilities: Capabilities;
      linkedEntity?: LinkedEntity;
      entityRebindable?: Rebindable;
      entityContract?: Contract;
      definerKnobs?: Definer;
    }
    ? true
    : never
  : never;
const _surfaceCoversSignature: _AssertSurfaceCoversSignature = true;
void _surfaceCoversSignature;
